class Node:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def remove_nth_from_end(head, n: int):
    dummy = Node(0, head)
    fast = slow = dummy
    for _ in range(n):
        if fast.next is None:
            return head
        fast = fast.next
    while fast.next:
        fast = fast.next
        slow = slow.next
    slow.next = slow.next.next
    return dummy.next
